{"name": "pi_harmonic_program", "type": "code/python", "content": "import mpmath

def get_pi_digit(position: int) -> int:
    """
    Retrieves the nth digit of Pi using BBP formula.
    """
    return int(mpmath.nstr(mpmath.pi, position + 1)[-1])

def check_static_mapping(positions: list[int]) -> dict:
    """
    Checks if Pi digits at certain positions follow static harmonic recurrence.
    """
    results = {}
    for pos in positions:
        digit = get_pi_digit(pos)
        prev_digit = get_pi_digit(pos - 1) if pos > 1 else None
        results[pos] = {"digit": digit, "preceding": prev_digit}
    return results

# Example test to verify static mappings
positions_to_test = [5, 6, 56, 57, 92, 93]
results = check_static_mapping(positions_to_test)
print(results)"}
